const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

/**
 * Native extension targets that are not generated by any Expo plugin. Sources live next to this
 * file (the source of truth) and are copied into `ios/<name>/`; the Xcode targets are added with
 * deterministic ids, so applying this twice (script or prebuild) changes nothing.
 */
const EXTENSIONS = [
  {
    name: 'NixShareExtension',
    bundleSuffix: 'ShareExtension',
    deploymentTarget: '16.4',
    extensionApiOnly: true,
    sources: ['ShareViewController.swift'],
  },
  {
    name: 'NixNotificationService',
    bundleSuffix: 'NotificationService',
    deploymentTarget: '16.4',
    extensionApiOnly: true,
    sources: ['NotificationService.swift'],
  },
  {
    name: 'NixCaptureExtension',
    bundleSuffix: 'CaptureExtension',
    deploymentTarget: '18.0',
    extensionApiOnly: true,
    sources: ['NixCaptureExtension.swift'],
  },
];

/** Swift files compiled into several targets (group `NiXShared`). */
const SHARED = {
  group: 'NiXShared',
  files: ['NixCaptureIntent.swift'],
  targets: ['NiX', 'ExpoWidgetsTarget', 'NixCaptureExtension'],
};

const APP_TARGET = 'NiX';

function uuid(key) {
  return crypto.createHash('md5').update(`nix-native-extension:${key}`).digest('hex').slice(0, 24).toUpperCase();
}

function quote(value) {
  return /^[A-Za-z0-9_./]+$/.test(value) ? value : `"${value}"`;
}

function section(objects, name) {
  if (!objects[name]) objects[name] = {};
  return objects[name];
}

function put(objects, sectionName, id, value, comment) {
  const target = section(objects, sectionName);
  target[id] = value;
  if (comment) target[`${id}_comment`] = comment;
}

function findTarget(objects, name) {
  const targets = section(objects, 'PBXNativeTarget');
  const id = Object.keys(targets).find((key) => !key.endsWith('_comment') && targets[key].name?.replace(/"/g, '') === name);
  return id ? { id, target: targets[id] } : null;
}

function phaseOf(objects, target, sectionName) {
  const phases = section(objects, sectionName);
  const ref = target.buildPhases.find((phase) => phases[phase.value]);
  return ref ? phases[ref.value] : null;
}

function copySources(projectRoot, platformRoot) {
  const root = path.join(projectRoot, 'plugins', 'native-extensions');
  for (const folder of [...EXTENSIONS.map((extension) => extension.name), SHARED.group]) {
    const from = path.join(root, folder);
    const to = path.join(platformRoot, folder);
    fs.mkdirSync(to, { recursive: true });
    for (const file of fs.readdirSync(from)) fs.copyFileSync(path.join(from, file), path.join(to, file));
  }
}

function appSettings(objects, appTarget) {
  const lists = section(objects, 'XCConfigurationList');
  const configs = section(objects, 'XCBuildConfiguration');
  const list = lists[appTarget.buildConfigurationList];
  const first = configs[list.buildConfigurations[0].value].buildSettings;
  return {
    team: first.DEVELOPMENT_TEAM,
    bundleId: String(first.PRODUCT_BUNDLE_IDENTIFIER).replace(/"/g, ''),
    marketingVersion: first.MARKETING_VERSION,
    buildNumber: first.CURRENT_PROJECT_VERSION,
  };
}

function addExtension(objects, projectId, app, extension) {
  const { name } = extension;
  const targetId = uuid(`${name}:target`);
  if (section(objects, 'PBXNativeTarget')[targetId]) return;

  const settings = appSettings(objects, app.target);
  const productRef = uuid(`${name}:product`);
  const groupId = uuid(`${name}:group`);
  const sourcesPhase = uuid(`${name}:sources`);
  const resourcesPhase = uuid(`${name}:resources`);
  const frameworksPhase = uuid(`${name}:frameworks`);
  const configList = uuid(`${name}:configList`);
  const proxyId = uuid(`${name}:proxy`);
  const dependencyId = uuid(`${name}:dependency`);
  const embedFile = uuid(`${name}:embed`);

  put(objects, 'PBXFileReference', productRef, {
    isa: 'PBXFileReference',
    explicitFileType: '"wrapper.app-extension"',
    includeInIndex: 0,
    path: `${name}.appex`,
    sourceTree: 'BUILT_PRODUCTS_DIR',
  }, `${name}.appex`);

  const children = [];
  const sourceBuildFiles = [];
  for (const file of [...extension.sources, 'Info.plist', `${name}.entitlements`]) {
    const fileRef = uuid(`${name}:file:${file}`);
    const isSwift = file.endsWith('.swift');
    put(objects, 'PBXFileReference', fileRef, {
      isa: 'PBXFileReference',
      lastKnownFileType: isSwift ? 'sourcecode.swift' : file.endsWith('.plist') ? 'text.plist.xml' : 'text.plist.entitlements',
      path: quote(file),
      sourceTree: '"<group>"',
    }, file);
    children.push({ value: fileRef, comment: file });
    if (isSwift) {
      const buildFile = uuid(`${name}:build:${file}`);
      put(objects, 'PBXBuildFile', buildFile, { isa: 'PBXBuildFile', fileRef, fileRef_comment: file }, `${file} in Sources`);
      sourceBuildFiles.push({ value: buildFile, comment: `${file} in Sources` });
    }
  }
  put(objects, 'PBXGroup', groupId, { isa: 'PBXGroup', children, path: name, sourceTree: '"<group>"' }, name);
  const project = section(objects, 'PBXProject')[projectId];
  section(objects, 'PBXGroup')[project.mainGroup].children.push({ value: groupId, comment: name });

  put(objects, 'PBXSourcesBuildPhase', sourcesPhase, {
    isa: 'PBXSourcesBuildPhase', buildActionMask: 2147483647, files: sourceBuildFiles, runOnlyForDeploymentPostprocessing: 0,
  }, 'Sources');
  put(objects, 'PBXResourcesBuildPhase', resourcesPhase, {
    isa: 'PBXResourcesBuildPhase', buildActionMask: 2147483647, files: [], runOnlyForDeploymentPostprocessing: 0,
  }, 'Resources');
  put(objects, 'PBXFrameworksBuildPhase', frameworksPhase, {
    isa: 'PBXFrameworksBuildPhase', buildActionMask: 2147483647, files: [], runOnlyForDeploymentPostprocessing: 0,
  }, 'Frameworks');

  const configIds = ['Debug', 'Release'].map((configName) => {
    const id = uuid(`${name}:config:${configName}`);
    put(objects, 'XCBuildConfiguration', id, {
      isa: 'XCBuildConfiguration',
      buildSettings: {
        APPLICATION_EXTENSION_API_ONLY: extension.extensionApiOnly ? 'YES' : 'NO',
        CODE_SIGN_ENTITLEMENTS: `${name}/${name}.entitlements`,
        CODE_SIGN_IDENTITY: '"Apple Development"',
        CODE_SIGN_STYLE: 'Automatic',
        CURRENT_PROJECT_VERSION: settings.buildNumber,
        DEVELOPMENT_TEAM: settings.team,
        GENERATE_INFOPLIST_FILE: 'NO',
        INFOPLIST_FILE: `${name}/Info.plist`,
        IPHONEOS_DEPLOYMENT_TARGET: extension.deploymentTarget,
        LD_RUNPATH_SEARCH_PATHS: '"$(inherited) @executable_path/Frameworks @executable_path/../../Frameworks"',
        MARKETING_VERSION: settings.marketingVersion,
        PRODUCT_BUNDLE_IDENTIFIER: `${settings.bundleId}.${extension.bundleSuffix}`,
        PRODUCT_NAME: '"$(TARGET_NAME)"',
        SKIP_INSTALL: 'YES',
        SWIFT_OPTIMIZATION_LEVEL: configName === 'Debug' ? '"-Onone"' : '"-O"',
        SWIFT_VERSION: '5.0',
        TARGETED_DEVICE_FAMILY: '1',
      },
      name: configName,
    }, configName);
    return { value: id, comment: configName };
  });
  put(objects, 'XCConfigurationList', configList, {
    isa: 'XCConfigurationList',
    buildConfigurations: configIds,
    defaultConfigurationIsVisible: 0,
    defaultConfigurationName: 'Release',
  }, `Build configuration list for PBXNativeTarget "${name}"`);

  put(objects, 'PBXNativeTarget', targetId, {
    isa: 'PBXNativeTarget',
    buildConfigurationList: configList,
    buildConfigurationList_comment: `Build configuration list for PBXNativeTarget "${name}"`,
    buildPhases: [
      { value: sourcesPhase, comment: 'Sources' },
      { value: frameworksPhase, comment: 'Frameworks' },
      { value: resourcesPhase, comment: 'Resources' },
    ],
    buildRules: [],
    dependencies: [],
    name,
    productName: name,
    productReference: productRef,
    productReference_comment: `${name}.appex`,
    productType: '"com.apple.product-type.app-extension"',
  }, name);
  project.targets.push({ value: targetId, comment: name });

  put(objects, 'PBXContainerItemProxy', proxyId, {
    isa: 'PBXContainerItemProxy',
    containerPortal: projectId,
    containerPortal_comment: 'Project object',
    proxyType: 1,
    remoteGlobalIDString: targetId,
    remoteInfo: name,
  }, 'PBXContainerItemProxy');
  put(objects, 'PBXTargetDependency', dependencyId, {
    isa: 'PBXTargetDependency',
    target: targetId,
    target_comment: name,
    targetProxy: proxyId,
    targetProxy_comment: 'PBXContainerItemProxy',
  }, 'PBXTargetDependency');
  app.target.dependencies.push({ value: dependencyId, comment: 'PBXTargetDependency' });

  put(objects, 'PBXBuildFile', embedFile, {
    isa: 'PBXBuildFile',
    fileRef: productRef,
    fileRef_comment: `${name}.appex`,
    settings: { ATTRIBUTES: ['RemoveHeadersOnCopy'] },
  }, `${name}.appex in Embed Foundation Extensions`);
  const copyPhases = section(objects, 'PBXCopyFilesBuildPhase');
  const embedRef = app.target.buildPhases.find((phase) => copyPhases[phase.value]?.dstSubfolderSpec === 13);
  if (!embedRef) throw new Error('The app target has no "Embed Foundation Extensions" phase.');
  copyPhases[embedRef.value].files.push({ value: embedFile, comment: `${name}.appex in Embed Foundation Extensions` });
}

function addShared(objects, projectId) {
  const groupId = uuid(`${SHARED.group}:group`);
  const groups = section(objects, 'PBXGroup');
  if (!groups[groupId]) {
    const children = SHARED.files.map((file) => {
      const fileRef = uuid(`${SHARED.group}:file:${file}`);
      put(objects, 'PBXFileReference', fileRef, {
        isa: 'PBXFileReference', lastKnownFileType: 'sourcecode.swift', path: quote(file), sourceTree: '"<group>"',
      }, file);
      return { value: fileRef, comment: file };
    });
    put(objects, 'PBXGroup', groupId, { isa: 'PBXGroup', children, path: SHARED.group, sourceTree: '"<group>"' }, SHARED.group);
    const project = section(objects, 'PBXProject')[projectId];
    groups[project.mainGroup].children.push({ value: groupId, comment: SHARED.group });
  }
  for (const targetName of SHARED.targets) {
    const found = findTarget(objects, targetName);
    if (!found) continue;
    const sources = phaseOf(objects, found.target, 'PBXSourcesBuildPhase');
    for (const file of SHARED.files) {
      const buildFile = uuid(`${SHARED.group}:${targetName}:${file}`);
      if (section(objects, 'PBXBuildFile')[buildFile]) continue;
      put(objects, 'PBXBuildFile', buildFile, {
        isa: 'PBXBuildFile', fileRef: uuid(`${SHARED.group}:file:${file}`), fileRef_comment: file,
      }, `${file} in Sources`);
      sources.files.push({ value: buildFile, comment: `${file} in Sources` });
    }
  }
}

/** Adds every extension target and the shared sources to an `xcode` project object. */
function applyNativeExtensions(project, { projectRoot, platformRoot }) {
  copySources(projectRoot, platformRoot);
  const objects = project.hash.project.objects;
  const projectId = project.hash.project.rootObject;
  const app = findTarget(objects, APP_TARGET);
  if (!app) throw new Error(`Missing app target ${APP_TARGET}`);
  for (const extension of EXTENSIONS) addExtension(objects, projectId, app, extension);
  addShared(objects, projectId);
  return project;
}

module.exports = { applyNativeExtensions, EXTENSIONS };
